mapper.select:
SELECT page_id::TEXT AS row_id, title, use_yn FROM t_page WHERE use_yn = 'Y'
AND title LIKE '%' || #{filterKeyword} || '%'
ORDER BY page_id DESC LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE t_page SET title = #{title}, context = #{context},
    upd_id = #{updId}, upd_dt = NOW(), upd_ip = #{updIp}
WHERE page_id = #{rowId}::integer
